class RandomExercisesResponseDto {
  RandomExercisesResponseDto({
    this.message,
    this.totalExercises,
    this.exercises,
  });

  RandomExercisesResponseDto.fromJson(dynamic json) {
    message = json['message'];
    totalExercises = json['totalExercises'];
    if (json['exercises'] != null) {
      exercises = [];
      json['exercises'].forEach((v) {
        exercises?.add(ExerciseDto.fromJson(v));
      });
    }
  }

  late final String? message;
  late final num? totalExercises;
  late final List<ExerciseDto>? exercises;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    map['message'] = message;
    map['totalExercises'] = totalExercises;
    if (exercises != null) {
      map['exercises'] = exercises?.map((v) => v.toJson()).toList();
    }
    return map;
  }

  RandomExercisesResponseEntity convertIntoEntity() {
    List<ExerciseEntity>? exercisesEntities;
    if (exercises != null) {
      exercisesEntities = [];
      for (var exercise in exercises!) {
        if (exercise.shortYoutubeDemonstrationLink == null &&
            exercise.inDepthYoutubeExplanationLink == null) {
          continue;
        } else {
          exercisesEntities.add(exercise.convertIntoEntity());
        }
      }
    }
    return RandomExercisesResponseEntity(
      message: message,
      totalExercises: totalExercises,
      exercises: exercisesEntities,
    );
  }
}

